export type HttpMethod = 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';

export type ParamLocation = 'path' | 'query' | 'header' | 'body';

export interface ParamBoundaryCase {
  id: string;
  label: string;
  /**
   * Logical type of this boundary, e.g. 'normal', 'empty', 'min', 'max', 'invalid'.
   * Only for UI grouping, server does not enforce semantics.
   */
  kind: string;
  value: unknown;
  description?: string;
  enabled: boolean;
}

export interface ApiParamConfig {
  name: string;
  location: ParamLocation;
  type: 'string' | 'number' | 'boolean' | 'json';
  required: boolean;
  description?: string;
  defaultValue?: unknown;
  boundaryCases: ParamBoundaryCase[];
}

export interface CoreBeApiEndpoint {
  id: string;
  category: string;
  name: string;
  method: HttpMethod;
  path: string;
  description?: string;
  tags?: string[];
  params: ApiParamConfig[];
}

export type ExecutionMode = 'single' | 'batch' | 'sequence';

export interface ApiTestCaseInput {
  id: string;
  title: string;
  paramsOverride: Record<string, unknown>;
}

export interface CoreBeRunRequest {
  endpointId: string;
  mode?: ExecutionMode;
  /**
   * Optional override for base URL; when omitted, per-user apiTests.baseUrl is used.
   */
  baseUrlOverride?: string;
  /**
   * Optional additional/override headers; merged on top of per-user defaultHeaders.
   */
  headersOverride?: Record<string, string>;
  cases: ApiTestCaseInput[];
}

export interface ApiTestCaseResult {
  id: string;
  title: string;
  ok: boolean;
  status: number;
  durationMs: number;
  error?: string;
  request: {
    method: HttpMethod;
    url: string;
    headers: Record<string, string>;
    bodyPreview?: string | null;
  };
  response: {
    status: number;
    headers: Record<string, string>;
    bodyText: string;
    truncated: boolean;
  };
}

export interface CoreBeRunResponse {
  endpointId: string;
  baseUrl: string;
  mode: ExecutionMode;
  results: ApiTestCaseResult[];
}

